541	/**
542	 * 整单盘点校正：首次提交先逐项核对当前余量与预期账面量，任一不符整单拒绝并
543	 * 说明冲突商品及当前量；全部相符才把列出的商品校正为实盘量（差额 = 实盘 - 账面，
544	 * 可增、可减、可为零），未列出的商品及其他仓库不变。同编号同内容重放只返回原
545	 * 结果，即使余量改变或盘点已冲销也不再核对、不再生效。
546	 */
547	function submitCount(dataDir: string, store: Store, req: CountRequest): SubmitOutcome {
548	  const content = canonicalCountContent(req);
549	  const existed = store.docs[req.docId];
550	  if (existed !== undefined) {
551	    if (stableStringify(existed.content) !== stableStringify(content))
552	      throw new BizError(`单据编号 ${req.docId} 已用于业务内容不同的单据，拒绝提交`);
553	    return { duplicate: true, lines: existed.resultLines }; // 幂等：返回原结果，不动库存
554	  }
555	  // 编号空间与入库/出库/调拨/冲销单共用
556	  if (store.reversals[req.docId] !== undefined)
557	    throw new BizError(`单据编号 ${req.docId} 已用于冲销单，拒绝提交`);
558	
559	  const pids = [...req.items.keys()].sort();
560	  for (const pid of pids) {
561	    if (store.products[pid] === undefined) throw new BizError(`商品未登记，拒绝整单：${pid}`);
562	  }
563	
564	  // 账面核对：任一商品的当前余量与预期账面量不符，整单拒绝并说明冲突商品及当前量
565	  const conflicts: string[] = [];
566	  for (const pid of pids) {
567	    const current = getStock(store.stock, pid, req.wh);
568	    const expected = req.items.get(pid)!.expected;
569	    if (current !== expected)
570	      conflicts.push(`商品 ${pid}：当前余量 ${current}，预期账面量 ${expected}`);
571	  }
572	  if (conflicts.length > 0)
573	    throw new BizError(`盘点单 ${req.docId} 账面核对不符，拒绝整单：\n${conflicts.join('\n')}`);
574	
575	  const draft: Store['stock'] = cloneStock(store.stock);
576	  const additions: LedgerEntry[] = [];
577	  const reportLines: string[] = [];
578	  let seq = store.entries.length;
579	
580	  for (const pid of pids) {
581	    const { expected, actual } = req.items.get(pid)!;
582	    const before = getStock(draft, pid, req.wh); // 核对通过，与预期账面量一致
583	    const after = actual;
584	    const diff = actual - expected; // 差额 = 实盘 - 账面，可增、可减、可为零
585	    setStock(draft, pid, req.wh, after);
586	    additions.push({
587	      seq: ++seq, doc: req.docId, type: 'count', product: pid, wh: req.wh,
588	      expected, actual, diff, before, after,
589	    });
590	    reportLines.push(
591	      `盘点 ${pid} @${req.wh} 账面=${expected} 实盘=${actual} 差额=${fmtSigned(diff)}：${before} -> ${after}`,
592	    );
593	  }
594	
595	  // 全部明细合法：一次性提交并在保存成功后才算成功
596	  store.stock = draft;
597	  store.entries.push(...additions);
598	  store.docs[req.docId] = { content, resultLines: reportLines };
599	  saveStore(dataDir, store);
600	
601	  return {
602	    duplicate: false,
603	    lines: [`盘点单 ${req.docId} 提交成功，仓库 ${req.wh}，共 ${pids.length} 种商品：`, ...reportLines],
604	  };
605	}
