607	/**
608	 * 整单冲销：在“当前余量”上应用原单的相反变动（不回滚历史、不恢复绝对余量）。
609	 * 任一商品扣回不足或补回后溢出，则整单拒绝、不留任何痕迹；成功后库存/流水/冲销
610	 * 关系/结果一起原子保存。
611	 */
612	function submitReversal(dataDir: string, store: Store, revId: string, origId: string): SubmitOutcome {
613	  const existed = store.reversals[revId];
614	  if (existed !== undefined) {
615	    if (existed.orig !== origId)
616	      throw new BizError(
617	        `冲销单编号 ${revId} 已用于冲销原单 ${existed.orig}，不能改冲原单 ${origId}，拒绝提交`,
618	      );
619	    return { duplicate: true, lines: existed.resultLines }; // 幂等重放：返回原冲销结果，不再变动
620	  }
621	  // 冲销单与入库/出库/调拨/盘点共用唯一编号空间
622	  if (store.docs[revId] !== undefined)
623	    throw new BizError(`编号 ${revId} 已是入库/出库/调拨/盘点单编号，不能用作冲销单，拒绝提交`);
624	
625	  // 只能冲销成功的原始库存单据：不存在的原单、冲销单本身均不可冲销
626	  const origRec = store.docs[origId];
627	  if (origRec === undefined)
628	    throw new BizError(`原单 ${origId} 不存在或不是成功的原始库存单据，拒绝冲销`);
629	
630	  for (const [existingRev, rec] of Object.entries(store.reversals)) {
631	    if (rec.orig === origId)
632	      throw new BizError(`原单 ${origId} 已被冲销单 ${existingRev} 成功冲销，每张原单只能冲销一次`);
633	  }
634	
635	  const c = origRec.content;
636	  const type = c.type as DocType | 'count';
637	  const items = c.items as Record<string, number>;
638	  const pids = Object.keys(items).sort();
639	
640	  const draft: Store['stock'] = cloneStock(store.stock);
641	  const additions: LedgerEntry[] = [];
642	  const reportLines: string[] = [];
643	  let seq = store.entries.length;
644	  const typeLabel = type === 'in' ? '入库' : type === 'out' ? '出库' : type === 'transfer' ? '调拨' : '盘点';
645	  const revType = `${type}-rev` as EntryType;
646	
647	  for (const pid of pids) {
648	    if (type === 'count') {
649	      // 冲销盘点：在当前余量上减去原盘点差额（不恢复原账面绝对值）；零差额不改余量但须记录
650	      const wh = c.wh as string;
651	      const item = (c.items as Record<string, { expected: number; actual: number }>)[pid];
652	      const diff = item.actual - item.expected;
653	      const before = getStock(draft, pid, wh);
654	      const after = before - diff;
655	      if (after < 0)
656	        throw new BizError(
657	          `冲销盘点原单 ${origId}：商品 ${pid} 仓库 ${wh} 当前余量 ${before} 冲减差额 ${fmtSigned(diff)} 后为负，拒绝整单`,
658	        );
659	      if (after > MAX_SAFE)
660	        throw new BizError(
661	          `冲销盘点原单 ${origId}：商品 ${pid} 仓库 ${wh} 冲减差额 ${fmtSigned(diff)} 后超出安全整数范围，拒绝整单`,
662	        );
663	      setStock(draft, pid, wh, after);
664	      additions.push({
665	        seq: ++seq, doc: revId, type: revType, product: pid, wh,
666	        expected: item.expected, actual: item.actual, diff, before, after, orig: origId,
667	      });
668	      reportLines.push(
669	        `冲销盘点 原单=${origId} 商品=${pid} @${wh} 反向差额=${fmtSigned(-diff)}：${before} -> ${after}`,
670	      );
671	      continue;
672	    }
673	    const qty = items[pid]; // 原单同商品合并后的数量
674	
675	    if (type === 'in') {
676	      // 冲销入库：从原目标仓扣回
677	      const wh = c.wh as string;
678	      const before = getStock(draft, pid, wh);
679	      if (before < qty)
680	        throw new BizError(
681	          `冲销入库原单 ${origId}：商品 ${pid} 仓库 ${wh} 当前余量 ${before} 不足扣回 ${qty}，拒绝整单`,
682	        );
683	      const after = before - qty;
684	      setStock(draft, pid, wh, after);
685	      additions.push({
686	        seq: ++seq, doc: revId, type: revType, product: pid, wh, qty, before, after, orig: origId,
687	      });
688	      reportLines.push(`冲销入库 原单=${origId} 商品=${pid} @${wh} -${qty}：${before} -> ${after}`);
689	    } else if (type === 'out') {
690	      // 冲销出库：向原来源仓补回
691	      const wh = c.wh as string;
692	      const before = getStock(draft, pid, wh);
693	      const after = before + qty;
694	      if (after > MAX_SAFE)
695	        throw new BizError(
696	          `冲销出库原单 ${origId}：商品 ${pid} 仓库 ${wh} 补回后余量超出安全整数范围，拒绝整单`,
697	        );
698	      setStock(draft, pid, wh, after);
699	      additions.push({
700	        seq: ++seq, doc: revId, type: revType, product: pid, wh, qty, before, after, orig: origId,
701	      });
702	      reportLines.push(`冲销出库 原单=${origId} 商品=${pid} @${wh} +${qty}：${before} -> ${after}`);
703	    } else {
704	      // 冲销调拨：从原调入仓扣回，向原调出仓补回
705	      const from = c.from as string;
706	      const to = c.to as string;
707	      const beforeTo = getStock(draft, pid, to);
708	      if (beforeTo < qty)
709	        throw new BizError(
710	          `冲销调拨原单 ${origId}：商品 ${pid} 原调入仓 ${to} 当前余量 ${beforeTo} 不足扣回 ${qty}，拒绝整单`,
711	        );
712	      const afterTo = beforeTo - qty;
713	      const beforeFrom = getStock(draft, pid, from);
714	      const afterFrom = beforeFrom + qty;
715	      if (afterFrom > MAX_SAFE)
716	        throw new BizError(
717	          `冲销调拨原单 ${origId}：商品 ${pid} 原调出仓 ${from} 补回后余量超出安全整数范围，拒绝整单`,
718	        );
719	      setStock(draft, pid, to, afterTo);
720	      setStock(draft, pid, from, afterFrom);
721	      additions.push({
722	        seq: ++seq, doc: revId, type: revType, product: pid, wh: to,
723	        qty, before: beforeTo, after: afterTo, from, to, orig: origId,
724	      });
725	      additions.push({
726	        seq: ++seq, doc: revId, type: revType, product: pid, wh: from,
727	        qty, before: beforeFrom, after: afterFrom, from, to, orig: origId,
728	      });
729	      reportLines.push(
730	        `冲销调拨 原单=${origId} 商品=${pid} ${to} -> ${from} ${qty}：` +
731	          `${to} ${beforeTo}->${afterTo}；${from} ${beforeFrom}->${afterFrom}`,
732	      );
733	    }
734	  }
735	
736	  // 全部明细合法：库存、流水、冲销关系、结果一次性提交，保存成功才算成功
737	  store.stock = draft;
738	  store.entries.push(...additions);
739	  store.reversals[revId] = { orig: origId, resultLines: reportLines };
740	  saveStore(dataDir, store);
741	
742	  return {
743	    duplicate: false,
744	    lines: [
745	      `冲销单 ${revId} 提交成功，冲销${typeLabel}原单 ${origId}，共 ${pids.length} 种商品：`,
746	      ...reportLines,
747	    ],
748	  };
749	}
