For items array parsing (in/out/transfer):

```ts
function parseBatchItems(raw: unknown, at: string): Map<string, number> {
  if (!Array.isArray(raw) || raw.length === 0)
    throw new BizError(`${at}：items 必须是非空数组`);
  const merged = new Map<string, number>();
  for (const it of raw) {
    if (!isPlainObject(it) || typeof it.product !== 'string')
      throw new BizError(`${at}：明细必须是 {product, qty} 对象`);
    const pid = trimOrThrow(`${at} 的商品编号`, it.product);
    if (!isPosSafeInt(it.qty))
      throw new BizError(`${at}：商品 ${pid} 的数量必须为正安全整数`);
    const sum = (merged.get(pid) ?? 0) + it.qty;
    if (!Number.isSafeInteger(sum)) throw new BizError(`${at}：商品 ${pid} 累计数量超出安全整数范围`);
    merged.set(pid, sum);
  }
  return merged;
}
```

